import{_ as o,o as l,c as i,a2 as a}from"./chunks/framework.DnrXFDHb.js";const p=JSON.parse('{"title":"Codex model not found 怎么处理","description":"Codex 或 OpenAI 兼容工具提示 model not found 时，按模型名称、账号权限、Key 权限和配置读取顺序排查。","frontmatter":{"title":"Codex model not found 怎么处理","description":"Codex 或 OpenAI 兼容工具提示 model not found 时，按模型名称、账号权限、Key 权限和配置读取顺序排查。"},"headers":[],"relativePath":"troubleshooting/model-not-found.md","filePath":"troubleshooting/model-not-found.md","lastUpdated":1783061751000}'),t={name:"troubleshooting/model-not-found.md"};function d(n,e,r,c,s,h){return l(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="codex-model-not-found-怎么处理" tabindex="-1">Codex model not found 怎么处理 <a class="header-anchor" href="#codex-model-not-found-怎么处理" aria-label="Permalink to &quot;Codex model not found 怎么处理&quot;">​</a></h1><p><code>model not found</code>、<code>model_not_found</code> 或「模型不存在」通常表示工具请求的模型名称无法被当前账号调用。它不一定是 Base URL 错误。</p><p>Codex 接入 CCWS 时，Base URL 仍然保持：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://www.ccws.pro/v1</span></span></code></pre></div><h2 id="常见原因" tabindex="-1">常见原因 <a class="header-anchor" href="#常见原因" aria-label="Permalink to &quot;常见原因&quot;">​</a></h2><ul><li>模型名称写错。</li><li>当前账号没有该模型权限。</li><li>当前 API Key 所在分组不支持该模型。</li><li>Codex 或 CC Switch 仍在读取旧配置。</li><li>切换 Provider 后没有重启 Codex 或终端。</li></ul><h2 id="排查顺序" tabindex="-1">排查顺序 <a class="header-anchor" href="#排查顺序" aria-label="Permalink to &quot;排查顺序&quot;">​</a></h2><ol><li>确认当前启用的是 <code>CCWS</code> Provider。</li><li>确认 Base URL 是 <code>https://www.ccws.pro/v1</code>。</li><li>检查 Codex 配置里的模型名称是否和 CCWS 当前支持的模型一致。</li><li>回到 CCWS 控制台确认当前账号和 Key 是否有模型权限。</li><li>保存配置后，重启 Codex 客户端或重新打开终端。</li><li>再发送一次简单测试请求。</li></ol><h2 id="不要优先改这些" tabindex="-1">不要优先改这些 <a class="header-anchor" href="#不要优先改这些" aria-label="Permalink to &quot;不要优先改这些&quot;">​</a></h2><ul><li>不要把 Base URL 改成完整接口路径。</li><li>不要把官网根地址当成 Codex Base URL。</li><li>不要把其他账号的 API Key 混到当前配置中。</li><li>不要把真实 API Key 发到聊天窗口或群聊里让别人排查。</li></ul><h2 id="如果使用-cc-switch" tabindex="-1">如果使用 CC Switch <a class="header-anchor" href="#如果使用-cc-switch" aria-label="Permalink to &quot;如果使用 CC Switch&quot;">​</a></h2><p>打开 CC Switch，确认：</p><ul><li>当前 Codex 启用的是 <code>CCWS</code>。</li><li>API 请求地址是 <code>https://www.ccws.pro/v1</code>。</li><li>API Key 已更新为当前账号的有效 Key。</li><li>启用后已经重启 Codex。</li></ul><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="/guide/cc-switch-provider">CC Switch 添加 CCWS Provider</a></li><li><a href="/guide/codex-api-key">Codex API Key 配置</a></li><li><a href="/troubleshooting/integration">工具兼容</a></li><li><a href="/troubleshooting/request-error">请求错误</a></li></ul>',15)])])}const C=o(t,[["render",d]]);export{p as __pageData,C as default};
